CREATE OR REPLACE FUNCTION "public"."accept_org_invite"("invite_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invite org_invites%ROWTYPE;
  v_user_email text;
  v_org_id uuid;
  v_role text;
BEGIN
  -- Get current user's email
  SELECT email INTO v_user_email FROM auth.users WHERE id = auth.uid();

  -- Find and validate the invite
  SELECT * INTO v_invite
  FROM org_invites
  WHERE token = invite_token
  AND status = 'pending'
  AND expires_at > now();

  IF v_invite.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid or expired invite');
  END IF;

  -- Check email matches
  IF v_invite.email != v_user_email THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invite was sent to a different email');
  END IF;

  -- Check if already a member
  IF EXISTS (
    SELECT 1 FROM org_memberships
    WHERE org_id = v_invite.org_id
    AND user_id = auth.uid()
  ) THEN
    -- Update invite to accepted anyway
    UPDATE org_invites
    SET status = 'accepted', accepted_at = now(), accepted_by = auth.uid()
    WHERE id = v_invite.id;

    RETURN jsonb_build_object('success', true, 'message', 'Already a member', 'org_id', v_invite.org_id);
  END IF;

  -- Create membership
  INSERT INTO org_memberships (org_id, user_id, role, status, joined_at)
  VALUES (v_invite.org_id, auth.uid(), v_invite.role, 'active', now());

  -- Update invite
  UPDATE org_invites
  SET status = 'accepted', accepted_at = now(), accepted_by = auth.uid()
  WHERE id = v_invite.id;

  RETURN jsonb_build_object('success', true, 'org_id', v_invite.org_id, 'role', v_invite.role);
END;
$$;


ALTER FUNCTION "public"."accept_org_invite"("invite_token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_org_invite"("invite_token" "text") IS 'Accepts an org invite using the token';



CREATE OR REPLACE FUNCTION "public"."activate_module_for_org"("p_org_id" "uuid", "p_module_slug" "text", "p_license_source" "text" DEFAULT 'addon'::"text", "p_trial_days" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_module_id UUID;
    v_license_id UUID;
    v_status TEXT := 'active';
    v_trial_start TIMESTAMPTZ;
    v_trial_end TIMESTAMPTZ;
BEGIN
    SELECT id INTO v_module_id FROM product_modules WHERE slug = p_module_slug AND is_active = true;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Module % not found or inactive', p_module_slug;
    END IF;

    IF p_trial_days IS NOT NULL THEN
        v_status := 'trialing';
        v_trial_start := now();
        v_trial_end := now() + (p_trial_days || ' days')::INTERVAL;
    END IF;

    INSERT INTO org_module_licenses (org_id, module_id, status, license_source, trial_start, trial_end)
    VALUES (p_org_id, v_module_id, v_status, p_license_source, v_trial_start, v_trial_end)
    ON CONFLICT (org_id, module_id) DO UPDATE SET
        status = EXCLUDED.status,
        license_source = EXCLUDED.license_source,
        trial_start = EXCLUDED.trial_start,
        trial_end = EXCLUDED.trial_end,
        activated_at = now(),
        updated_at = now()
    RETURNING id INTO v_license_id;

    RETURN v_license_id;
END;
$$;


ALTER FUNCTION "public"."activate_module_for_org"("p_org_id" "uuid", "p_module_slug" "text", "p_license_source" "text", "p_trial_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_custom_module_column"("p_org_id" "uuid", "p_api_name" "text", "p_field_api_name" "text", "p_field_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    table_name TEXT;
    column_type TEXT;
BEGIN
    table_name := 'crm_custom_' || REPLACE(LEFT(p_org_id::TEXT, 8), '-', '') || '_' || p_api_name;

    column_type := CASE p_field_type
        WHEN 'text' THEN 'TEXT'
        WHEN 'textarea' THEN 'TEXT'
        WHEN 'number' THEN 'INTEGER'
        WHEN 'decimal' THEN 'DECIMAL(15,2)'
        WHEN 'currency' THEN 'DECIMAL(15,2)'
        WHEN 'percent' THEN 'DECIMAL(5,2)'
        WHEN 'email' THEN 'TEXT'
        WHEN 'phone' THEN 'TEXT'
        WHEN 'url' THEN 'TEXT'
        WHEN 'date' THEN 'DATE'
        WHEN 'datetime' THEN 'TIMESTAMPTZ'
        WHEN 'checkbox' THEN 'BOOLEAN DEFAULT false'
        WHEN 'picklist' THEN 'TEXT'
        WHEN 'multi_picklist' THEN 'TEXT[]'
        WHEN 'lookup' THEN 'UUID'
        WHEN 'multi_lookup' THEN 'UUID[]'
        WHEN 'auto_number' THEN 'TEXT'
        ELSE 'TEXT'
    END;

    EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS %I %s',
        table_name, p_field_api_name, column_type);
END;
$$;


ALTER FUNCTION "public"."add_custom_module_column"("p_org_id" "uuid", "p_api_name" "text", "p_field_api_name" "text", "p_field_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_custom_module_column"("p_org_id" "uuid", "p_api_name" "text", "p_field_api_name" "text", "p_field_type" "text") IS 'Adds a new column to an existing custom module table';



CREATE OR REPLACE FUNCTION "public"."add_to_priority_lane"("p_org_id" "uuid", "p_lane_id" "uuid", "p_lead_id" "uuid", "p_reason" "text" DEFAULT NULL::"text", "p_owner_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item_id uuid;
  v_existing_id uuid;
BEGIN
  -- Check if already in this lane
  SELECT id INTO v_existing_id
  FROM priority_items
  WHERE org_id = p_org_id
    AND lane_id = p_lane_id
    AND lead_id = p_lead_id
    AND completed_at IS NULL;

  IF v_existing_id IS NOT NULL THEN
    -- Update existing item
    UPDATE priority_items
    SET
      reason = COALESCE(p_reason, reason),
      owner_user_id = COALESCE(p_owner_user_id, owner_user_id),
      updated_at = now()
    WHERE id = v_existing_id;
    RETURN v_existing_id;
  END IF;

  -- Create new item
  INSERT INTO priority_items (
    org_id,
    lane_id,
    lead_id,
    reason,
    owner_user_id,
    score,
    source
  )
  VALUES (
    p_org_id,
    p_lane_id,
    p_lead_id,
    p_reason,
    COALESCE(p_owner_user_id, auth.uid()),
    50, -- Default score
    'manual'
  )
  RETURNING id INTO v_item_id;

  RETURN v_item_id;
END;
$$;


ALTER FUNCTION "public"."add_to_priority_lane"("p_org_id" "uuid", "p_lane_id" "uuid", "p_lead_id" "uuid", "p_reason" "text", "p_owner_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_purge_user_dependencies"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  r record;
  aid uuid;
  sql text;
  rows_deleted bigint;
  tables_touched int := 0;
  warnings text[] := ARRAY[]::text[];
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'user_id is required';
  END IF;

  -- Tables that must be cleared (no ON DELETE CASCADE from auth.users)
  BEGIN
    DELETE FROM public.impersonation_log
    WHERE admin_id = p_user_id OR target_user_id = p_user_id;
  EXCEPTION WHEN OTHERS THEN
    warnings := array_append(warnings, 'impersonation_log: ' || SQLERRM);
  END;

  BEGIN
    DELETE FROM public.phi_access_log WHERE user_id = p_user_id;
  EXCEPTION WHEN OTHERS THEN
    warnings := array_append(warnings, 'phi_access_log: ' || SQLERRM);
  END;

  -- Purge rows blocking advisor_profiles deletion (before auth cascade).
  FOR aid IN
    SELECT id FROM public.advisor_profiles
    WHERE id = p_user_id OR user_id = p_user_id
  LOOP
    FOR r IN
      SELECT att.attname AS column_name, cl.relname AS table_name
      FROM pg_constraint con
      JOIN pg_class cl ON cl.oid = con.conrelid
      JOIN pg_namespace ns ON ns.oid = cl.relnamespace
      JOIN pg_class ref_cl ON ref_cl.oid = con.confrelid
      JOIN pg_namespace ref_ns ON ref_ns.oid = ref_cl.relnamespace
      JOIN LATERAL unnest(con.conkey) AS ck(attnum) ON true
      JOIN pg_attribute att ON att.attrelid = con.conrelid AND att.attnum = ck.attnum
      WHERE con.contype = 'f'
        AND ref_ns.nspname = 'public'
        AND ref_cl.relname = 'advisor_profiles'
        AND ns.nspname = 'public'
        AND con.confdeltype IN ('a', 'r')
    LOOP
      BEGIN
        sql := format('DELETE FROM public.%I WHERE %I = $1', r.table_name, r.column_name);
        EXECUTE sql USING aid;
        GET DIAGNOSTICS rows_deleted = ROW_COUNT;
        IF rows_deleted > 0 THEN
          tables_touched := tables_touched + 1;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        warnings := array_append(
          warnings,
          format('%s.%s (advisor %s): %s', r.table_name, r.column_name, aid, SQLERRM)
        );
      END;
    END LOOP;
  END LOOP;

  -- Purge rows blocking public.profiles deletion.
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN
    FOR r IN
      SELECT att.attname AS column_name, cl.relname AS table_name
      FROM pg_constraint con
      JOIN pg_class cl ON cl.oid = con.conrelid
      JOIN pg_namespace ns ON ns.oid = cl.relnamespace
      JOIN pg_class ref_cl ON ref_cl.oid = con.confrelid
      JOIN pg_namespace ref_ns ON ref_ns.oid = ref_cl.relnamespace
      JOIN LATERAL unnest(con.conkey) AS ck(attnum) ON true
      JOIN pg_attribute att ON att.attrelid = con.conrelid AND att.attnum = ck.attnum
      WHERE con.contype = 'f'
        AND ref_ns.nspname = 'public'
        AND ref_cl.relname = 'profiles'
        AND ns.nspname = 'public'
        AND con.confdeltype IN ('a', 'r')
    LOOP
      BEGIN
        sql := format('DELETE FROM public.%I WHERE %I = $1', r.table_name, r.column_name);
        EXECUTE sql USING p_user_id;
        GET DIAGNOSTICS rows_deleted = ROW_COUNT;
        IF rows_deleted > 0 THEN
          tables_touched := tables_touched + 1;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        warnings := array_append(
          warnings,
          format('%s.%s (profile): %s', r.table_name, r.column_name, SQLERRM)
        );
      END;
    END LOOP;
  END IF;

  -- Purge all public tables with RESTRICT/NO ACTION FKs to auth.users.
  FOR r IN
    SELECT att.attname AS column_name, cl.relname AS table_name
    FROM pg_constraint con
    JOIN pg_class cl ON cl.oid = con.conrelid
    JOIN pg_namespace ns ON ns.oid = cl.relnamespace
    JOIN pg_class ref_cl ON ref_cl.oid = con.confrelid
    JOIN pg_namespace ref_ns ON ref_ns.oid = ref_cl.relnamespace
    JOIN LATERAL unnest(con.conkey) AS ck(attnum) ON true
    JOIN pg_attribute att ON att.attrelid = con.conrelid AND att.attnum = ck.attnum
    WHERE con.contype = 'f'
      AND ref_ns.nspname = 'auth'
      AND ref_cl.relname = 'users'
      AND ns.nspname = 'public'
      AND con.confdeltype IN ('a', 'r')
  LOOP
    BEGIN
      sql := format('DELETE FROM public.%I WHERE %I = $1', r.table_name, r.column_name);
      EXECUTE sql USING p_user_id;
      GET DIAGNOSTICS rows_deleted = ROW_COUNT;
      IF rows_deleted > 0 THEN
        tables_touched := tables_touched + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      warnings := array_append(
        warnings,
        format('%s.%s (auth.users): %s', r.table_name, r.column_name, SQLERRM)
      );
    END;
  END LOOP;

  -- Identity rows (safe to remove before auth delete; advisor_profiles cascades from auth if any remain).
  BEGIN
    DELETE FROM public.user_roles WHERE user_id = p_user_id;
  EXCEPTION WHEN OTHERS THEN
    warnings := array_append(warnings, 'user_roles: ' || SQLERRM);
  END;

  BEGIN
    DELETE FROM public.admin_users WHERE id = p_user_id;
  EXCEPTION WHEN OTHERS THEN
    warnings := array_append(warnings, 'admin_users: ' || SQLERRM);
  END;

  BEGIN
    DELETE FROM public.advisor_profiles WHERE id = p_user_id OR user_id = p_user_id;
  EXCEPTION WHEN OTHERS THEN
    warnings := array_append(warnings, 'advisor_profiles: ' || SQLERRM);
  END;

  BEGIN
    DELETE FROM public.profiles WHERE id = p_user_id;
  EXCEPTION WHEN OTHERS THEN
    warnings := array_append(warnings, 'profiles: ' || SQLERRM);
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'tables_with_deletions', tables_touched,
    'warnings', to_jsonb(warnings)
  );
END;
$_$;


ALTER FUNCTION "public"."admin_purge_user_dependencies"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_purge_user_dependencies"("p_user_id" "uuid") IS 'Removes public-schema rows referencing auth.users before admin-delete-user hard-deletes the auth account.';



CREATE OR REPLACE FUNCTION "public"."advisor_can_access_lead"("p_lead_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.lead_submissions ls
    WHERE ls.id = p_lead_id
      AND ls.assigned_to = auth.uid()
  );
$$;


ALTER FUNCTION "public"."advisor_can_access_lead"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aggregate_daily_analytics"("target_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  summary_record RECORD;
BEGIN
  -- Calculate daily summary
  SELECT
    COUNT(DISTINCT session_id) as total_sessions,
    COUNT(DISTINCT COALESCE(user_id::text, session_id)) as total_users,
    COUNT(DISTINCT CASE WHEN is_new_visitor THEN session_id END) as new_users,
    COUNT(DISTINCT CASE WHEN NOT is_new_visitor THEN session_id END) as returning_users,
    COALESCE(SUM(page_count), 0) as total_page_views,
    COALESCE(AVG(CASE WHEN is_bounce THEN 100 ELSE 0 END), 0) as bounce_rate,
    COALESCE(AVG(duration_seconds), 0) as avg_session_duration,
    COALESCE(AVG(page_count), 0) as pages_per_session,
    COUNT(CASE WHEN device_type = 'desktop' THEN 1 END) as desktop_sessions,
    COUNT(CASE WHEN device_type = 'mobile' THEN 1 END) as mobile_sessions,
    COUNT(CASE WHEN device_type = 'tablet' THEN 1 END) as tablet_sessions
  INTO summary_record
  FROM analytics_sessions
  WHERE DATE(started_at) = target_date;
  
  -- Upsert daily summary
  INSERT INTO daily_analytics_summary (
    date, total_sessions, total_users, new_users, returning_users,
    total_page_views, bounce_rate, avg_session_duration, pages_per_session,
    desktop_sessions, mobile_sessions, tablet_sessions, updated_at
  ) VALUES (
    target_date,
    COALESCE(summary_record.total_sessions, 0),
    COALESCE(summary_record.total_users, 0),
    COALESCE(summary_record.new_users, 0),
    COALESCE(summary_record.returning_users, 0),
    COALESCE(summary_record.total_page_views, 0),
    COALESCE(summary_record.bounce_rate, 0),
    COALESCE(summary_record.avg_session_duration, 0),
    COALESCE(summary_record.pages_per_session, 0),
    COALESCE(summary_record.desktop_sessions, 0),
    COALESCE(summary_record.mobile_sessions, 0),
    COALESCE(summary_record.tablet_sessions, 0),
    now()
  )
  ON CONFLICT (date) DO UPDATE SET
    total_sessions = EXCLUDED.total_sessions,
    total_users = EXCLUDED.total_users,
    new_users = EXCLUDED.new_users,
    returning_users = EXCLUDED.returning_users,
    total_page_views = EXCLUDED.total_page_views,
    bounce_rate = EXCLUDED.bounce_rate,
    avg_session_duration = EXCLUDED.avg_session_duration,
    pages_per_session = EXCLUDED.pages_per_session,
    desktop_sessions = EXCLUDED.desktop_sessions,
    mobile_sessions = EXCLUDED.mobile_sessions,
    tablet_sessions = EXCLUDED.tablet_sessions,
    updated_at = now();
END;
$$;


ALTER FUNCTION "public"."aggregate_daily_analytics"("target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."array_append_unique"("arr" "text"[], "new_value" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF arr IS NULL THEN
    RETURN ARRAY[new_value];
  ELSIF new_value = ANY(arr) THEN
    RETURN arr;
  ELSE
    RETURN array_append(arr, new_value);
  END IF;
END;
$$;


ALTER FUNCTION "public"."array_append_unique"("arr" "text"[], "new_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_user_role"("target_user_id" "uuid", "target_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    new_row user_roles%ROWTYPE;
    default_org UUID := '00000000-0000-4000-a000-000000000001';
    mpb_org UUID;
    already_had boolean := false;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM user_roles
        WHERE user_id = auth.uid() AND role = 'super_admin'
    ) THEN
        RAISE EXCEPTION 'Access denied: super_admin role required';
    END IF;

    IF target_role NOT IN (
      'super_admin', 'admin', 'advisor', 'member', 'crm_user', 'concierge', 'staff_hr'
    ) THEN
        RAISE EXCEPTION 'Invalid role: %', target_role;
    END IF;

    SELECT id INTO mpb_org FROM public.organizations WHERE slug = 'mpb-health' LIMIT 1;
    IF mpb_org IS NULL THEN
      mpb_org := default_org;
    END IF;

    INSERT INTO user_roles (user_id, role, granted_by)
    VALUES (target_user_id, target_role, auth.uid())
    ON CONFLICT (user_id, role) DO NOTHING
    RETURNING * INTO new_row;

    IF new_row.id IS NULL THEN
        already_had := true;
        SELECT * INTO new_row
        FROM user_roles
        WHERE user_id = target_user_id AND role = target_role
        LIMIT 1;
    END IF;

    IF target_role = 'crm_user' THEN
        INSERT INTO org_memberships (user_id, org_id, role, status, joined_at)
        VALUES (target_user_id, default_org, 'member', 'active', now())
        ON CONFLICT (user_id, org_id)
        DO UPDATE SET status = 'active', joined_at = COALESCE(org_memberships.joined_at, now());
    END IF;

    IF target_role IN ('admin', 'super_admin') THEN
        INSERT INTO admin_users (id, email, role, status)
        SELECT target_user_id, u.email, target_role, 'active'
        FROM auth.users u WHERE u.id = target_user_id
        ON CONFLICT (id)
        DO UPDATE SET status = 'active', role = EXCLUDED.role;
    END IF;

    -- HR Staff Admin: keep/create Staff Hub identity + roster profile
    IF target_role = 'staff_hr' THEN
        INSERT INTO admin_users (id, email, role, status, first_name, last_name)
        SELECT
          target_user_id,
          u.email,
          COALESCE(NULLIF(au.role, ''), 'staff'),
          'active',
          COALESCE(au.first_name, split_part(u.email, '@', 1)),
          COALESCE(au.last_name, '')
        FROM auth.users u
        LEFT JOIN public.admin_users au ON au.id = u.id
        WHERE u.id = target_user_id
        ON CONFLICT (id) DO UPDATE
          SET status = 'active',
              email = EXCLUDED.email;

        INSERT INTO public.staff_profiles (
          org_id, user_id, display_name, email, title, is_active
        )
        SELECT
          mpb_org,
          au.id,
          COALESCE(
            NULLIF(trim(concat_ws(' ', au.first_name, au.last_name)), ''),
            split_part(au.email, '@', 1)
          ),
          lower(au.email),
          au.title,
          true
        FROM public.admin_users au
        WHERE au.id = target_user_id
        ON CONFLICT (org_id, user_id) DO UPDATE
          SET is_active = true,
              email = EXCLUDED.email,
              display_name = CASE
                WHEN staff_profiles.display_name = '' THEN EXCLUDED.display_name
                ELSE staff_profiles.display_name
              END;
    END IF;

    IF already_had THEN
        RETURN jsonb_build_object(
          'success', true,
          'message', 'Role already assigned',
          'id', new_row.id,
          'user_id', new_row.user_id,
          'role', new_row.role::text
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'id', new_row.id,
        'user_id', new_row.user_id,
        'role', new_row.role::text,
        'created_at', new_row.created_at
    );
END;
$$;


ALTER FUNCTION "public"."assign_user_role"("target_user_id" "uuid", "target_role" "text") OWNER TO "postgres";


