WHEN sent_count > 0 THEN (opened_count::numeric / sent_count::numeric) * 100
ELSE 0
END,
click_rate = CASE
WHEN sent_count > 0 THEN (clicked_count::numeric / sent_count::numeric) * 100
ELSE 0
END,
updated_at = now()
WHERE id = campaign_uuid;
END;
