CREATE OR REPLACE FUNCTION "public"."get_org_features"("p_org_id" "uuid") RETURNS TABLE("feature_slug" "text", "feature_name" "text", "category" "text", "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        ff.slug,
        ff.name,
        ff.category,
        CASE
            WHEN ofo.id IS NOT NULL THEN 'override'
            WHEN ff.enabled_by_default THEN 'default'
            ELSE 'plan_tier'
        END AS source
    FROM feature_flags ff
    LEFT JOIN org_feature_overrides ofo ON ofo.feature_id = ff.id AND ofo.org_id = p_org_id
    WHERE org_has_feature(p_org_id, ff.slug) = true
    ORDER BY ff.slug;
END;
$$;


ALTER FUNCTION "public"."get_org_features"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_org_modules"("p_org_id" "uuid") RETURNS TABLE("module_slug" "text", "module_name" "text", "category" "text", "license_source" "text", "status" "text", "activated_at" timestamp with time zone, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        pm.slug,
        pm.name,
        pm.category,
        oml.license_source,
        oml.status,
        oml.activated_at,
        oml.expires_at
    FROM org_module_licenses oml
    JOIN product_modules pm ON pm.id = oml.module_id
    WHERE oml.org_id = p_org_id
      AND oml.status IN ('active', 'trialing')
      AND (oml.expires_at IS NULL OR oml.expires_at > now())
    ORDER BY pm.sort_order;
END;
$$;


ALTER FUNCTION "public"."get_org_modules"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_plan_rate"("p_plan_slug" "text", "p_age" integer, "p_member_type" "text", "p_iua_amount" numeric DEFAULT NULL::numeric, "p_effective_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("plan_id" "uuid", "plan_name" "text", "monthly_contribution" numeric, "enrollment_fee" numeric, "annual_membership_fee" numeric, "tobacco_surcharge_pct" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pl.id AS plan_id,
    pl.name AS plan_name,
    pp.monthly_contribution,
    pl.enrollment_fee,
    pl.annual_membership_fee,
    pl.tobacco_surcharge_pct
  FROM public.plans pl
  JOIN public.plan_pricing pp ON pp.plan_id = pl.id
  WHERE pl.slug = p_plan_slug
    AND pl.is_active = true
    AND pp.effective_date <= p_effective_date
    AND p_age >= pp.age_min
    AND p_age <= pp.age_max
    AND pp.member_type = p_member_type
    AND (p_iua_amount IS NULL AND pp.iua_amount IS NULL
         OR pp.iua_amount = p_iua_amount)
  ORDER BY pp.effective_date DESC
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."get_plan_rate"("p_plan_slug" "text", "p_age" integer, "p_member_type" "text", "p_iua_amount" numeric, "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_plan_resource_by_slug"("p_slug" "text") RETURNS TABLE("id" "uuid", "plan_slug" "text", "plan_name" "text", "description" "text", "icon" "text", "color" "text", "overview_content" "text", "pricing_content" "text", "handbook_url" "text", "handbook_title" "text", "flyer_url" "text", "flyer_title" "text", "qrg_url" "text", "qrg_title" "text", "state_guidelines" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    apr.id,
    apr.plan_slug,
    apr.plan_name,
    apr.description,
    apr.icon,
    apr.color,
    apr.overview_content,
    apr.pricing_content,
    apr.handbook_url,
    apr.handbook_title,
    apr.flyer_url,
    apr.flyer_title,
    apr.qrg_url,
    apr.qrg_title,
    apr.state_guidelines
