    AS $$
DECLARE
  v_meeting advisor_meetings;
BEGIN
  UPDATE advisor_meetings
  SET
    status = 'live',
    started_at = NOW()
  WHERE id = p_meeting_id
  RETURNING * INTO v_meeting;

  RETURN v_meeting;
END;
